var data = msg.payload;
data.received = new Date().toISOString();

// Simpan data terakhir
flow.set('lastSensor', data);

// Simpan history (maks 50)
var history = flow.get('history') || [];
history.push(data);
if (history.length > 50) history.shift();
flow.set('history', history);

// === CEK THRESHOLD ===
var threshold = flow.get('threshold') || null;
var notifMsg = null;

if (threshold !== null && data.suhu > threshold) {
    var lastNotif = flow.get('lastNotifTime') || 0;
    var now = Date.now();
    // Throttle notifikasi: minimal 10 detik antara notifikasi
    if (now - lastNotif > 10000) {
        flow.set('lastNotifTime', now);
        notifMsg = {
            payload: {
                type: 'threshold_alert',
                message: 'PERINGATAN: Suhu melewati batas!',
                suhu: data.suhu,
                threshold: threshold,
                timestamp: data.received
            },
            topic: 'threshold'
        };
    }
}

// Kirim ke WebSocket output
var wsMsg = { payload: JSON.stringify({
    type: 'sensor_update',
    data: data
})};

return [msg, wsMsg, notifMsg];

// API Key yang valid (simpan di environment variable di production)
var VALID_API_KEYS = ['iot-secret-2024', 'dev-key-123'];

var apiKey = msg.req.headers['x-api-key'];

if (!apiKey || !VALID_API_KEYS.includes(apiKey)) {
    msg.statusCode = 401;
    msg.payload = {
        status: 'error',
        message: 'Unauthorized: X-API-Key tidak valid atau tidak ada',
        hint: 'Tambahkan header X-API-Key: iot-secret-2024'
    };
    msg.headers = {
        'Access-Control-Allow-Origin': '*',
        'Content-Type': 'application/json'
    };
    return [null, msg];
}

// Auth berhasil, lanjutkan ke handler
return [msg, null];

var VALID_API_KEYS = ['iot-secret-2024', 'dev-key-123'];
var apiKey = msg.req.headers['x-api-key'];
if (!apiKey || !VALID_API_KEYS.includes(apiKey)) {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'Unauthorized: Header X-API-Key diperlukan' };
    msg.headers = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json' };
    return [null, msg];
}
return [msg, null];

var data = flow.get('lastSensor') || { suhu: null, kelembaban: null, led: null, timestamp: null };
var threshold = flow.get('threshold') || null;

msg.payload = {
    status: 'success',
    data: data,
    threshold: threshold,
    alert: threshold !== null && data.suhu !== null && data.suhu > threshold,
    server_time: new Date().toISOString()
};
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Content-Type': 'application/json'
};
return msg;

var VALID_API_KEYS = ['iot-secret-2024', 'dev-key-123'];
var apiKey = msg.req.headers['x-api-key'];
if (!apiKey || !VALID_API_KEYS.includes(apiKey)) {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'Unauthorized: Header X-API-Key diperlukan' };
    msg.headers = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json' };
    return [null, msg];
}
return [msg, null];

var history = flow.get('history') || [];
var limit = parseInt(msg.req.query.limit) || 50;
var data = history.slice(-limit);

msg.payload = {
    status: 'success',
    count: data.length,
    limit: limit,
    data: data
};
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Content-Type': 'application/json'
};
return msg;

var VALID_API_KEYS = ['iot-secret-2024', 'dev-key-123'];
var apiKey = msg.req.headers['x-api-key'];
if (!apiKey || !VALID_API_KEYS.includes(apiKey)) {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'Unauthorized: Header X-API-Key diperlukan' };
    msg.headers = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json' };
    return [null, msg];
}
return [msg, null];

var body = msg.payload;

if (!body.device || !body.action) {
    msg.statusCode = 400;
    msg.payload = {
        status: 'error',
        message: 'Field "device" dan "action" wajib diisi'
    };
    msg.headers = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json' };
    return [msg, null];
}

var validDevices = ['lamp', 'fan', 'pump'];
var validActions = ['on', 'off', 'toggle'];

if (!validDevices.includes(body.device)) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: 'Device tidak dikenal: ' + body.device };
    msg.headers = { 'Access-Control-Allow-Origin': '*' };
    return [msg, null];
}

// Publish ke MQTT
var mqttMsg = {
    payload: JSON.stringify(body),
    topic: 'iot/kontrol'
};

msg.statusCode = 200;
msg.payload = {
    status: 'success',
    message: 'Perintah berhasil dikirim',
    sent: body,
    timestamp: new Date().toISOString()
};
msg.headers = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json' };

return [msg, mqttMsg];

var VALID_API_KEYS = ['iot-secret-2024', 'dev-key-123'];
var apiKey = msg.req.headers['x-api-key'];
if (!apiKey || !VALID_API_KEYS.includes(apiKey)) {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'Unauthorized: Header X-API-Key diperlukan' };
    msg.headers = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json' };
    return [null, msg];
}
return [msg, null];

var body = msg.payload;

if (body.threshold === undefined || body.threshold === null) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: 'Field "threshold" (angka) wajib diisi' };
    msg.headers = { 'Access-Control-Allow-Origin': '*' };
    return msg;
}

var nilai = parseFloat(body.threshold);
if (isNaN(nilai) || nilai < 0 || nilai > 100) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: 'Threshold harus angka antara 0-100' };
    msg.headers = { 'Access-Control-Allow-Origin': '*' };
    return msg;
}

flow.set('threshold', nilai);

msg.statusCode = 200;
msg.payload = {
    status: 'success',
    message: 'Threshold berhasil diperbarui',
    threshold: nilai,
    unit: '°C',
    updated_at: new Date().toISOString()
};
msg.headers = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json' };
return msg;

var VALID_API_KEYS = ['iot-secret-2024', 'dev-key-123'];
var apiKey = msg.req.headers['x-api-key'];
if (!apiKey || !VALID_API_KEYS.includes(apiKey)) {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'Unauthorized' };
    msg.headers = { 'Access-Control-Allow-Origin': '*' };
    return msg;
}
var threshold = flow.get('threshold');
msg.payload = {
    status: 'success',
    threshold: threshold !== undefined ? threshold : null,
    unit: '°C'
};
msg.headers = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json' };
return msg;

msg.statusCode = 204;
msg.payload = '';
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, X-API-Key',
    'Access-Control-Max-Age': '86400'
};
return msg;
